onal": false}], "steps": ["Toss the pork with soy sauce, wine and egg. Coat each cube in cornstarch.", "Heat the oil to 350 F (175 C). Fry the pork in batches 3 min until pale gold. Drain.", "Simmer the ketchup, vinegar, sugar and water 2 min. Stir in the starch slurry and cook until glossy.", "Raise the oil to 375 F and fry the pork again for 1 min until crisp. Drain.", "In a wok, stir-fry the pepper and onion 2 min over high heat. Add the pineapple and sauce and bring to a bubble.", "Fold in the pork off the heat and serve at once."]}, {"slug": "hui-guo-rou", "title": "Hui Guo Rou (Twice-Cooked Pork)", "cuisine": "Chinese", "prep_time_min": 20, "cook_time_min": 40, "servings": 4, "spice_level": 3, "cookware": ["Wok"], "notes": "Chill the boiled pork before slicing so you can cut it paper-thin.", "ingredients": [{"sort_order": 1, "quantity": 1.0, "unit": "lb", "name": "pork belly", "prep_note": "in one slab", "is_optional": false}, {"sort_order": 2, "quantity": 3.0, "unit": "slice", "name": "ginger", "prep_note": "for the boil", "is_optional": false}, {"sort_order": 3, "quantity": 2.0, "unit": null, "name": "scallion", "prep_note": "for the boil", "is_optional": false}, {"sort_order": 4, "quantity": 2.0, "unit": "tbsp", "name": "vegetable oil", "prep_note": null, "is_optional": false}, {"sort_order": 5, "quantity": 2.0, "unit": "tbsp", "name": "doubanjiang", "prep_note": null, "is_optional": false}, {"sort_order": 6, "quantity": 1.0, "unit": "tbsp", "name": "sweet bean sauce", "prep_note": null, "is_optional": false}, {"sort_order": 7, "quantity": 1.0, "unit": "tbsp", "name": "fermented black beans", "prep_note": "rinsed, chopped", "is_optional": false}, {"sort_order": 8, "quantity": 3.0, "unit": "clove", "name": "garlic", "prep_note": "sliced", "is_optional": false}, {"sort_order": 9, "quantity": 6.0, "unit": "oz", "name": "leek", "prep_note": "trimmed, sliced on the diagonal (about 2 leeks)", "is_optional": false}, {"sort_order": 10, "quantity": 1.0, "unit": "tbsp", "name": "shaoxing wine", "prep_note": null, "is_optional": false}, {"sort_order": 11, "quantity": 1.0, "unit": "tsp", "name": "granulated sugar", "prep_note": null, "is_optional": false}], "steps": ["Simmer the pork in water with ginger and scallion 30 min, until a chopstick slides in. Cool, then chill 1 hour.", "Slice the pork very thin, about 1/8 inch.", "Heat the oil in a wok over high heat. Fry the pork slices 3 min, until the edges curl and the fat renders.", "Push aside. Fry the doubanjiang, sweet bean sauce and black beans 1 min, until the oil turns red.", "Add the garlic, leeks, wine and sugar. Toss 2 min, until the leeks soften but keep some bite.", "Serve with rice."]}, {"slug": "yu-xiang-qiezi", "title": "Yu Xiang Qiezi (Fish-Fragrant Eggplant)", "cuisine": "Chinese", "prep_time_min": 15, "cook_time_min": 20, "servings": 4, "spice_level": 2, "cookware": ["Wok"], "notes": "Salt the eggplant first; it absorbs less oil and goes silky instead of greasy.", "ingredients": [{"sort_order": 1, "quantity": 1.25, "unit": "lb", "name": "chinese eggplant", "prep_note": "cut in batons", "is_optional": false}, {"sort_order": 2, "quantity": 1.0, "unit": "tsp", "name": "salt", "prep_note": null, "is_optional": false}, {"sort_order": 3, "quantity": 4.0, "unit": "oz", "name": "ground pork", "prep_note": null, "is_optional": false}, {"sort_order": 4, "quantity": 3.0, "unit": "tbsp", "name": "vegetable oil", "prep_note": "divided", "is_optional": false}, {"sort_order": 5, "quantity": 2.0, "unit": "tbsp", "name": "doubanjiang", "prep_note": null, "is_optional": false}, {"sort_order": 6, "quantity": 4.0, "unit": "clove", "name": "garlic", "prep_note": "minced", "is_optional": false}, {"sort_order": 7, "quantity": 1.0, "unit": "tbsp", "name": "ginger", "prep_note": "minced", "is_optional": false}, {"sort_order": 8, "quantity": 3.0, "unit": null, "name": "scallion", "prep_note": "whites minced, greens sliced", "is_optional": false}, {"sort_order": 9, "quantity": 1.0, "unit": 