l.", "ingredients": [{"sort_order": 1, "quantity": 1.0, "unit": "lb", "name": "cod", "prep_note": "fillets, or sea bass", "is_optional": false}, {"sort_order": 2, "quantity": 0.5, "unit": "tsp", "name": "salt", "prep_note": null, "is_optional": false}, {"sort_order": 3, "quantity": 2.0, "unit": "tbsp", "name": "ginger", "prep_note": "cut in fine matchsticks", "is_optional": false}, {"sort_order": 4, "quantity": 3.0, "unit": null, "name": "scallion", "prep_note": "cut in fine matchsticks", "is_optional": false}, {"sort_order": 5, "quantity": 2.0, "unit": "tbsp", "name": "soy sauce", "prep_note": null, "is_optional": false}, {"sort_order": 6, "quantity": 1.0, "unit": "tbsp", "name": "shaoxing wine", "prep_note": null, "is_optional": false}, {"sort_order": 7, "quantity": 1.0, "unit": "tsp", "name": "granulated sugar", "prep_note": null, "is_optional": false}, {"sort_order": 8, "quantity": 2.0, "unit": "tbsp", "name": "vegetable oil", "prep_note": null, "is_optional": false}, {"sort_order": 9, "quantity": 0.25, "unit": "cup", "name": "fresh cilantro", "prep_note": "sprigs", "is_optional": false}], "steps": ["Pat the fish dry and season with salt. Lay it on a heatproof plate and scatter half the ginger and scallion over.", "Steam over boiling water, covered, 8-10 min, until the fish is opaque and flakes.", "Pour off the liquid on the plate and discard the cooked ginger and scallion.", "Cover the fish with the remaining ginger, scallion and the cilantro.", "Mix the soy sauce, wine and sugar and pour around the fish.", "Heat the oil until it just begins to smoke and pour over the herbs; they will sizzle. Serve at once."]}, {"slug": "hong-shao-rou", "title": "Hong Shao Rou (Red-Braised Pork Belly)", "cuisine": "Chinese", "prep_time_min": 15, "cook_time_min": 80, "servings": 4, "spice_level": 0, "cookware": ["Pot"], "notes": "Let the sauce reduce to a lacquer at the end; it should cling to each piece.", "ingredients": [{"sort_order": 1, "quantity": 1.0, "unit": "lb", "name":