uantity": 1.0, "unit": null, "name": "egg", "prep_note": null, "is_optional": false}, {"sort_order": 12, "quantity": 0.5, "unit": "tsp", "name": "salt", "prep_note": "or to taste", "is_optional": false}], "steps": ["Heat the vegetable oil in a small pot over medium heat. Cook the pork belly and scallion whites 3 min, until the fat turns translucent.", "Add garlic, gochugaru, soy sauce and sesame oil. Stir 30 sec, until the oil turns red and smells toasty.", "Pour in the water and bring to a boil. Add the clams and cook 3-4 min, until the shells open. Discard any that stay shut.", "Spoon in the tofu in large chunks without breaking them up much. Simmer 5 min, until the stew bubbles hard around the edges.", "Season with salt. Crack the egg into the center and sprinkle with scallion greens.", "Take the pot to the table still bubbling and serve with rice. The egg cooks in the heat of the pot."]}, {"slug": "doenjang-jjigae", "title": "Doenjang Jjigae (Soybean Paste Stew)", "cuisine": "Korean", "prep_time_min": 15, "cook_time_min": 25, "servings": 3, "spice_level": 1, "cookware": ["Pot"], "notes": "Dissolve the paste through a sieve for a smooth broth with no grit.", "ingredients": [{"sort_order": 1, "quantity": 3.0, "unit": "cup", "name": "water", "prep_note": null, "is_optional": false}, {"sort_order": 2, "quantity": null, "unit": null, "name": "dried anchovies", "prep_note": "8, heads and guts removed (they flavor the broth and are strained out)", "is_optional": false}, {"sort_order": 3, "quantity": 1.0, "unit": "piece", "name": "kombu", "prep_note": "about 3 inches square", "is_optional": false}, {"sort_order": 4, "quantity": 3.0, "unit": "tbsp", "name": "doenjang", "prep_note": null, "is_optional": false}, {"sort_order": 5, "quantity": 1.0, "unit": "tsp", "name": "gochugaru", "prep_note": null, "is_optional": false}, {"sort_order": 6, "quantity": 6.0, "unit": "oz", "name": "potato", "prep_note": "peeled, cut in 1/2-inch cubes", "is_optional": false}, {"sort_order": 7, "quantity": 6.0, "unit": "oz", "name": "zucchini", "prep_note": "half-moons", "is_optional": false}, {"sort_order": 8, "quantity": 0.5, "unit": null, "name": "yellow onion", "prep_note": "cut in chunks", "is_optional": false}, {"sort_order": 9, "quantity": 4.0, "unit": "oz", "name": "shiitake mushrooms", "prep_note": "sliced", "is_optional": false}, {"sort_order": 10, "quantity": 7.0, "unit": "oz", "name": "firm tofu", "prep_note": "cut in 3/4-inch cubes", "is_optional": false}, {"sort_order": 11, "quantity": 3.0, "unit": "clove", "name": "garlic", "prep_note": "minced", "is_optional": false}, {"sort_order": 12, "quantity": 1.0, "unit": null, "name": "cheongyang pepper", "prep_note": "sliced", "is_optional": false}, {"sort_order": 13, "quantity": 1.0, "unit": null, "name": "scallion", "prep_note": "sliced", "is_optional": false}], "steps": ["Bring the water, anchovies and kombu to a boil in a pot. Remove the kombu after 5 min and simmer the anchovies another 5 min. Lift out the anchovies.", "Set a small sieve in the broth and stir the doenjang through it until dissolved. Add the gochugaru.", "Add the potato and cook 6 min, until the edges just turn tender.", "Add the onion, zucchini and mushrooms. Simmer 5 min, until the zucchini turns slightly translucent.", "Add the tofu, garlic and pepper. Simmer 3 min, until the tofu is hot through.", "Top with scallion and serve with rice."]}, {"slug": "galbi-jjim", "title": "Galbi Jjim (Braised Short Ribs)", "cuisine": "Korean", "prep_time_min": 30, "cook_time_min": 120, "servings": 4, "spice_level": 0, "cookware": ["Pot"], "notes": "Parboil the ribs first; it keeps the sauce clear instead of murky.", "ingredients": [{"sort_order": 1, "quantity": 1.8, "unit": "lb", "name": "short ribs", "prep_note": "edible meat weight; buy about 3 lb bone-in, cut Korean-style or in 2-inch pieces", "is_optional": false}, {"sort_order": 2, "quantity": 0.5, "unit": "cup", "name": "soy sauce", "prep_note": null, "is_optional": false}, {"sort_or