, "Bring to a boil, then cover and simmer on low 1 hour, until the meat starts to loosen from the bone.", "Add the carrot, radish, mushrooms, chestnuts and red dates. Simmer uncovered 40 min, stirring now and then, until the vegetables are tender and the sauce coats a spoon.", "Skim the fat from the top. Serve garnished with scallion."]}, {"slug": "dakgalbi", "title": "Dakgalbi (Spicy Stir-Fried Chicken)", "cuisine": "Korean", "prep_time_min": 20, "cook_time_min": 20, "servings": 3, "spice_level": 3, "cookware": ["Skillet"], "notes": "A little water in the pan keeps the sweet potato from scorching before it softens.", "ingredients": [{"sort_order": 1, "quantity": 1.5, "unit": "lb", "name": "chicken thighs", "prep_note": "boneless, skinless, bite-size pieces", "is_optional": false}, {"sort_order": 2, "quantity": 3.0, "unit": "tbsp", "name": "gochujang", "prep_note": null, "is_optional": false}, {"sort_order": 3, "quantity": 1.0, "unit": "tbsp", "name": "gochugaru", "prep_note": null, "is_optional": false}, {"sort_order": 4, "quantity": 2.0, "unit": "tbsp", "name": "soy sauce", "prep_note": null, "is_optional": false}, {"sort_order": 5, "quantity": 1.0, "unit": "tbsp", "name": "granulated sugar", "prep_note": null, "is_optional": false}, {"sort_order": 6, "quantity": 1.0, "unit": "tbsp", "name": "toasted sesame oil", "prep_note": null, "is_optional": false}, {"sort_order": 7, "quantity": 4.0, "unit": "clove", "name": "garlic", "prep_note": "minced", "is_optional": false}, {"sort_order": 8, "quantity": 1.0, "unit": "tsp", "name": "ginger", "prep_note": "grated", "is_optional": false}, {"sort_order": 9, "quantity": 8.0, "unit": "oz", "name": "sweet potato", "prep_note": "cut in 1/2-inch half-moons", "is_optional": false}, {"sort_order": 10, "quantity": 0.25, "unit": null, "name": "green cabbage", "prep_note": "cut in bite-size squares", "is_optional": false}, {"sort_order": 11, "quantity": 1.0, "unit": null, "name": "yellow onion", "prep_note": "sliced", "is_optional": 