", "is_optional": false}, {"sort_order": 6, "quantity": 0.5, "unit": "tsp", "name": "chinese five spice", "prep_note": null, "is_optional": false}, {"sort_order": 7, "quantity": 1.0, "unit": "tsp", "name": "granulated sugar", "prep_note": null, "is_optional": false}, {"sort_order": 8, "quantity": 1.0, "unit": null, "name": "egg", "prep_note": null, "is_optional": false}, {"sort_order": 9, "quantity": 0.75, "unit": "cup", "name": "potato starch", "prep_note": "sweet potato starch is traditional and gives a craggier crust", "is_optional": false}, {"sort_order": 10, "quantity": 0.25, "unit": "cup", "name": "vegetable oil", "prep_note": "about 3 cups to fill the pot; roughly this much is absorbed", "is_optional": false}, {"sort_order": 11, "quantity": 1.0, "unit": "cup", "name": "thai basil", "prep_note": "leaves, dry", "is_optional": false}, {"sort_order": 12, "quantity": 1.0, "unit": "tsp", "name": "salt", "prep_note": null, "is_optional": false}, {"sort_order": 13, "quantity": 0.5, "unit": "tsp", "name": "white pepper", "prep_note": null, "is_optional": false}], "steps": ["Toss the chicken with the soy sauce, wine, garlic, ginger, five-spice, sugar and egg. Marinate 30 min.", "Dredge each piece in sweet potato starch, pressing it on.", "Heat about 3 cups oil in a pot to 350 F (175 C). Fry the chicken in batches 3-4 min, until deep golden. Drain.", "Raise the oil to 375 F and re-fry for 1 min until crisp.", "Fry the basil 10-15 sec until crisp. Drain.", "Toss the chicken with the basil, salt and white pepper and serve hot."]}, {"slug": "thai-red-curry-chicken", "title": "Thai Red Curry with Chicken (Gaeng Phet Gai)", "cuisine": "Thai", "prep_time_min": 15, "cook_time_min": 20, "servings": 4, "spice_level": 3, "cookware": ["Pot"], "notes": "Fry the paste in thick coconut cream until the oil separates; that is where the flavor opens up.", "ingredients": [{"sort_order": 1, "quantity": 1.0, "unit": "can", "name": "coconut milk", "prep_note": "13.5 oz, unshaken, cream scoo